from itertools import product

# Formal model of the argument (a modeling choice, not a reading of the Analects text).
# D: Confucius abstained from out-of-season vegetables from time to time (the premise).
# O: out-of-season vegetables existed in his era.
# K: Confucius was very demanding about diet (option A).
# Ch: we can choose seasonal or out-of-season vegetables (option C).
# C: the explanation's conclusion, that the abstention is a meaningful practice, D and O.

VARS = ("D", "O", "K", "Ch")
ASSIGNMENTS = [dict(zip(VARS, vals)) for vals in product([False, True], repeat=len(VARS))]

def premise(a):
    return a["D"]

def conclusion(a):
    return a["D"] and a["O"]

def sufficient(x):
    # Premise plus option x must entail the conclusion in every assignment.
    return all((not (premise(a) and a[x])) or conclusion(a) for a in ASSIGNMENTS)

def necessary(x):
    # Every assignment where premise and conclusion hold must satisfy option x.
    return all((not (premise(a) and conclusion(a))) or a[x] for a in ASSIGNMENTS)

options = {"A": "K", "B": "O", "C": "Ch"}
submitted = "B"

print(f"assignments checked (exhaustive): {len(ASSIGNMENTS)}")
results = {}
for label, var in options.items():
    s = sufficient(var)
    n = necessary(var)
    results[label] = (s, n)
    print(f"option {label} ({var}): sufficient={s} necessary={n}")

valid_options = [label for label, (s, n) in results.items() if s and n]
print(f"options that are both sufficient and necessary: {valid_options}")
print(f"submitted answer: {submitted}")

if valid_options == [submitted]:
    print("CHECK PASS")
elif valid_options:
    print("CHECK FAIL")
else:
    print("CHECK UNKNOWN")
